/* Simplified from php-cgi query-string handling, pre-patch (CVE-2012-1823). */
/* If the query string has no unencoded '=', treat it as CLI arguments. */
if (query_string != NULL && strchr(query_string, '=') == NULL) {
    decoded = url_decode(query_string);
    php_build_argv(decoded, &argc, &argv);   /* e.g. "-d", "auto_prepend_file=..." */
    cgi_handle_args(argc, argv);             /* php interprets -d / -s / -r flags */
}

